  var st = steps[curStep];
  var i1 = document.getElementById('focalLengthF1Input'), o1 = document.getElementById('focalLengthF1Val');
  var i2 = document.getElementById('focalLengthF2Input'), o2 = document.getElementById('focalLengthF2Val');
  i1.value = st.f1; o1.value = st.f1;
  i2.value = st.f2; o2.value = st.f2;
  update_focalLengthF1(st.f1);      // slider update functions re-seat lens 2 (sep = null)
  update_focalLengthF2(st.f2);
  if (st.resetDi) S.di = DI0;
  if (st.sepOffset) S.sep = (st.f1 - st.f2) * st.sepOffset; // deliberately mis-seat for step 4
  redraw();
  [gRays, gMark].forEach(function (g) { g.attr('opacity', 0.25).animate(240).attr('opacity', 1); });
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + steps.length + ' · ' + st.title;
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

