var mkArc = draw.marker(18, 18, function (m) { m.polygon('0,0 18,9 0,18').attr('fill', INK); })
  .attr({ orient: 'auto', refX: 15, refY: 9, markerUnits: 'userSpaceOnUse' });

/* ── groups (z-order) ──────────────────────────────────────────────────── */
