  return 'M ' + (cx - edge) + ' ' + (yAxis - halfH) +
    ' C ' + (cx - waist) + ' ' + (yAxis - halfH * 0.55) + ' ' + (cx - waist) + ' ' + (yAxis + halfH * 0.55) + ' ' + (cx - edge) + ' ' + (yAxis + halfH) +
